const fs=require('node:fs'),vm=require('node:vm'),assert=require('node:assert/strict');
function model(name){const html=fs.readFileSync(__dirname+'/'+name+'.html','utf8'),box=vm.createContext({});for(const [i,m]of [...html.matchAll(/<script[^>]*>([\s\S]*?)<\/script>/g)].slice(0,2).entries())vm.runInContext(i===1?m[1].replace('return {actions,','return {threatCost,VALUE,actions,'):m[1],box);return {E:box.Yiwu,C:box.YiwuComputer};}
const baseline=model('baseline'),candidate=model('candidate'),{E,C}=candidate,copy=x=>JSON.parse(JSON.stringify(x));let checks=0,settlements=0,cases=0,changed=0,cardComparisons=0;const diagnostics=[];
const test=(name,fn)=>{fn();checks++;console.log('通过：'+name);};
function oracle(s,p){
  const original=baseline.C.threatCost(s,p),enemies=s.pieces.filter(q=>q.side!==p.side&&E.geometry(s,q,p.x,p.y,true));
  if(!original||p.kind==='king'||E.CHALLENGES[s.scenario])return original;
  return Math.max(...enemies.map(q=>{
    if(q.hp!==1)return original;
    const ctx=E.context(s,q,p),replies=C.choices(s,q,ctx),values=[];
    for(const id of C.choices(s,p,ctx)){
      let cost=0,reliable=true;
      for(const reply of replies){
        const next=copy(s);next.phase='duel';next.duel=E.context(next,E.get(next,q.id),E.get(next,p.id));E.resolve(next,reply,id);settlements++;
        const defender=E.get(next,p.id);if(E.get(next,q.id)||!defender){reliable=false;continue;}
        const lostCards=defender.exhausted.length-p.exhausted.length;if(lostCards)cardComparisons++;
        cost=Math.max(cost,next.phase==='ended'&&next.winner===p.side?0:(p.hp-defender.hp)*C.VALUE[p.kind]/36+lostCards*.15);
      }
      if(reliable)values.push(cost);
    }
    return Math.min(original,...values);
  }));
}
function verify(s,p){const before=JSON.stringify(s),expected=oracle(s,p),actual=C.threatCost(s,p);assert(Math.abs(actual-expected)<1e-12,[p.kind,p.hp,actual,expected].join(','));assert(actual>=0&&actual<=baseline.C.threatCost(s,p));assert.equal(JSON.stringify(s),before);cases++;if(actual<baseline.C.threatCost(s,p)-1e-12)changed++;return actual;}
function fixture(kind='rook',hp=18,qhp=1,support=0){
  const s=E.create('attrition'),x=kind==='elephant'?2:4,y=kind==='guard'?8:5,p=E.piece('defender','red',kind,x,y),q=E.piece('attacker','black','pawn',x,y-1);p.hp=hp;q.hp=qhp;
  s.pieces=[E.piece('rk','red','king',3,9),E.piece('bk','black','king',5,0),p,q];s.phase='board';s.turn='black';s.repetitions={};
  if(support>=1)s.pieces.push(E.piece('support-rook','red','rook',8,y));if(support>=2)s.pieces.push(E.piece('support-horse','red','horse',x+2,y+1));
  assert(E.canMove(s,q,x,y));return {s,p,q};
}
test('真实结算对照生命、耗牌、伤子、支援、学习与耗尽边界',()=>{
  for(const kind of ['rook','cannon','horse','pawn','guard','elephant']){
    const ids=Object.keys(E.CARDS).filter(id=>E.CARDS[id].kind===kind),learned=[[],[ids[0]],[ids[1]],[ids[2]],[ids[0],ids[1]],[ids[1],ids[2]]];
    for(const hp of [1,2,7,12,18])for(const qhp of [1,2])for(const support of [0,1,2])for(const cards of learned)for(const exhausted of [false,true]){
      const {s,p,q}=fixture(kind,hp,qhp,support);p.learned=[...cards];p.exhausted=exhausted?cards.slice(0,1):[];q.learned=Object.keys(E.CARDS).filter(id=>E.CARDS[id].kind==='pawn').slice(0,2);verify(s,p);
    }
  }
  assert(changed>0);assert(cardComparisons>0);
});
test('红黑旋转及另一名正常攻击者保留风险',()=>{
  for(const rotate of [false,true]){const {s,p}=fixture('rook',7);if(rotate){s.turn='red';for(const q of s.pieces){q.side=E.OTHER[q.side];q.x=8-q.x;q.y=9-q.y;}}
    verify(s,p);s.pieces.push(E.piece('extra',E.OTHER[p.side],'rook',rotate?8:0,p.y));assert.equal(verify(s,p),baseline.C.threatCost(s,p));}
});
test('上轮两处六血交换代价保留原受攻评分',()=>{
  for(const row of require('../counter-threat-v06122/audit-final.json').rows){let s;for(const [op,...args]of row.commands){if(op==='create')s=E.create(...args);else E[op](s,...args);}E.move(s,row.actual.id,row.actual.x,row.actual.y);for(const item of row.risk){const p=E.get(s,item.piece),actual=verify(s,p);assert.equal(actual,item.before);assert(actual>0);diagnostics.push({index:row.index,ply:row.ply,piece:p.id,cost:actual});}}
});
test('反杀将帅立即获胜时不再计入后续损失',()=>{
  const {s,p,q}=fixture('rook',18);q.kind='king';q.x=4;q.y=0;p.x=4;p.y=1;s.pieces=s.pieces.filter(x=>x.id!=='bk');assert(E.canMove(s,q,p.x,p.y));assert.equal(verify(s,p),0);
});
test('挑战与普通将帅保留原判断',()=>{
  for(const scenario of ['challenge-support','challenge-relay','challenge-tempo','attrition']){const s=E.create(scenario);for(const q of s.pieces){const hp=q.hp;q.hp=1;for(const p of s.pieces.filter(p=>scenario!=='attrition'||p.kind==='king'))assert.equal(C.threatCost(s,p),baseline.C.threatCost(s,p));q.hp=hp;}}
});
fs.writeFileSync(__dirname+'/targeted.json',JSON.stringify({checks,cases,actualSettlements:settlements,changedCases:changed,cardComparisons,diagnostics},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({checks,cases,actualSettlements:settlements,changedCases:changed,cardComparisons}));
